use ratatui::{prelude::*, widgets::*}; use crate::{app::App, widgets::status_bar};
pub fn draw(f:&mut Frame, app:&mut App, area:Rect){ let chunks=Layout::vertical([Constraint::Min(5),Constraint::Length(1)]).split(area); let text="SSHDeck Help\n\nKeyboard\n  ↑/k       up\n  ↓/j       down\n  Enter     connect/open\n  Esc       back/close modal\n  /         search\n  s         open files/SFTP\n  t         tunnel builder\n  r         run command\n  h         health check\n  Ctrl+p    command palette\n  q         quit\n\nMouse\n  Click row: select\n  Double click host: connect\n  Double click folder: open\n  Double click file: preview/open\n  Right click: context menu\n  Scroll wheel: scroll focused pane\n  Click buttons: run actions\n  Click tabs/sidebar: switch views\n  Click breadcrumbs: jump paths\n\nSSHDeck Files\n  j/k move · h/l parent/open · Space select · Tab dual-pane\n  right-click files for Preview/Edit/Download/Rename/Copy Path/Delete\n\nAccessibility\n  --ascii · --no-animations · --no-mouse · [ui].mouse=false"; f.render_widget(Paragraph::new(text).wrap(Wrap{trim:false}).block(Block::bordered().border_type(crate::design::borders::rounded(!app.ascii)).border_style(app.theme.border()).title(" Help ? ")), chunks[0]); status_bar::draw(f, app, chunks[1], "Esc back · q quit · mouse:on"); }
